<?php
declare(strict_types=1);
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
try{$c=require __DIR__.'/cms-config/database.php';$db=new PDO(sprintf('mysql:host=%s;port=%s;dbname=%s;charset=utf8mb4',$c['host'],$c['port'],$c['database']),$c['username'],$c['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){http_response_code(503);exit('Contenido temporalmente no disponible.');}
$lang=($_GET['lang']??'es')==='en'?'en':'es';$slug=trim((string)($_GET['slug']??''));$lineAlias=(string)($_GET['line']??'');$line=in_array($lineAlias,['retail','linea-retail','retail-line'],true)?'retail':'conventional';
$s=$db->prepare("SELECT p.id,p.image_path,l.slug line_slug,c.name_es category_es,c.name_en category_en,t.name,t.slug,t.short_description,t.description,t.seo_title,t.seo_description,COALESCE(sp.scientific_name,'') scientific_name,COALESCE(sp.tariff_code,'') tariff_code,COALESCE(IF(?='es',sp.caliber_es,sp.caliber_en),'') caliber,COALESCE(IF(?='es',sp.destinations_es,sp.destinations_en),'') destinations,COALESCE(sp.technical_sheet_path,'') technical_sheet_path FROM products p JOIN product_lines l ON l.id=p.line_id JOIN product_categories c ON c.id=p.category_id JOIN product_translations t ON t.product_id=p.id AND t.locale=? LEFT JOIN product_specs sp ON sp.product_id=p.id WHERE t.slug=? AND l.slug=? AND p.is_active=1 AND p.deleted_at IS NULL LIMIT 1");$s->execute([$lang,$lang,$lang,$slug,$line]);$p=$s->fetch();if(!$p){http_response_code(404);$title=$lang==='es'?'Producto no encontrado':'Product not found';?><!doctype html><html lang="<?=$lang?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?></title><link rel="stylesheet" href="/product-detail.css"><main class="not-found"><img src="/images/logo.webp" alt="Royal Beans Perú"><h1><?=h($title)?></h1><a href="<?=$lang==='es'?'/productos/':'/en/products/'?>"><?=$lang==='es'?'Volver a productos':'Back to products'?></a></main></html><?php exit;}
$category=$lang==='es'?$p['category_es']:$p['category_en'];$gallery=$db->prepare('SELECT * FROM product_gallery WHERE product_id=? ORDER BY sort_order,id');$gallery->execute([$p['id']]);$gallery=$gallery->fetchAll();array_unshift($gallery,['media_type'=>'image','media_path'=>$p['image_path'],'alt_es'=>$p['name'],'alt_en'=>$p['name']]);
$q=$db->prepare('SELECT * FROM product_packages WHERE product_id=? ORDER BY sort_order,id');$q->execute([$p['id']]);$packages=$q->fetchAll();$q=$db->prepare('SELECT month_number,availability FROM product_harvest WHERE product_id=?');$q->execute([$p['id']]);$harvest=array_column($q->fetchAll(),'availability','month_number');$q=$db->prepare('SELECT name FROM product_certifications WHERE product_id=? ORDER BY sort_order,id');$q->execute([$p['id']]);$certs=array_column($q->fetchAll(),'name');
$q=$db->prepare("SELECT p.id,p.image_path,t.name,t.slug,c.name_es,c.name_en FROM product_relations r JOIN products p ON p.id=r.related_product_id JOIN product_translations t ON t.product_id=p.id AND t.locale=? JOIN product_categories c ON c.id=p.category_id WHERE r.product_id=? AND p.is_active=1 AND p.deleted_at IS NULL ORDER BY r.sort_order LIMIT 3");$q->execute([$lang,$p['id']]);$related=$q->fetchAll();if(count($related)<3){$ids=array_merge([(int)$p['id']],array_map(fn($x)=>(int)$x['id'],$related));$marks=implode(',',array_fill(0,count($ids),'?'));$q=$db->prepare("SELECT p.id,p.image_path,t.name,t.slug,c.name_es,c.name_en FROM products p JOIN product_translations t ON t.product_id=p.id AND t.locale=? JOIN product_categories c ON c.id=p.category_id JOIN product_lines l ON l.id=p.line_id WHERE l.slug=? AND p.id NOT IN ($marks) AND p.is_active=1 AND p.deleted_at IS NULL ORDER BY p.sort_order LIMIT ?");$args=[$lang,$line,...$ids,3-count($related)];foreach($args as $i=>$v)$q->bindValue($i+1,$v,is_int($v)?PDO::PARAM_INT:PDO::PARAM_STR);$q->execute();$related=array_merge($related,$q->fetchAll());}
$months=$lang==='es'?['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic']:['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];$base=$lang==='es'?'/productos/'.($line==='retail'?'linea-retail':'linea-convencional').'/':'/en/products/'.($line==='retail'?'retail-line':'conventional-line').'/';$contact=$lang==='es'?'/contacto/':'/en/contact/';$title=$p['seo_title']?:$p['name'].' | Royal Beans Perú';$description=$p['seo_description']?:$p['short_description'];
?><!doctype html><html lang="<?=$lang?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?></title><meta name="description" content="<?=h($description)?>"><link rel="stylesheet" href="/product-detail.css"><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@type'=>'Product','name'=>$p['name'],'image'=>[$p['image_path']],'description'=>$description,'brand'=>['@type'=>'Brand','name'=>'Royal Beans Perú']],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script></head><body><header class="pd-header"><a class="pd-brand" href="<?=$lang==='es'?'/':'/en/'?>"><img src="/images/logo.webp" alt="Royal Beans Perú"><span><strong>ROYAL BEANS</strong><small>· PERÚ ·</small></span></a><nav><a href="<?=$lang==='es'?'/':'/en/'?>"><?=$lang==='es'?'Inicio':'Home'?></a><a href="<?=$lang==='es'?'/nosotros/':'/en/about-us/'?>"><?=$lang==='es'?'Nosotros':'About'?></a><a class="active" href="<?=$lang==='es'?'/productos/':'/en/products/'?>"><?=$lang==='es'?'Productos':'Products'?></a><a href="<?=$contact?>"><?=$lang==='es'?'Contáctanos':'Contact'?></a></nav><a class="pd-lang" href="<?=$lang==='es'?'/en/products/':'/productos/'?>"><?=$lang==='es'?'EN':'ES'?></a></header><main data-product-id="<?=$p['id']?>"><section class="product-hero"><div class="gallery"><div class="gallery-main"><?php $first=$gallery[0];?><img id="main-product-image" src="<?=h($first['media_path'])?>" alt="<?=h($p['name'])?>"></div><?php if(count($gallery)>1):?><div class="gallery-thumbs"><?php foreach($gallery as $i=>$item):if($item['media_type']!=='image')continue;?><button class="<?=$i===0?'active':''?>" data-image="<?=h($item['media_path'])?>" aria-label="<?=h(($lang==='es'?'Ver imagen ':'View image ').($i+1))?>"><img src="<?=h($item['media_path'])?>" alt=""></button><?php endforeach;?></div><?php endif;?></div><article class="product-copy"><a class="crumb" href="<?=h($base)?>">← <?=h($lang==='es'?'Volver a la línea de productos':'Back to product line')?></a><p class="eyebrow">· <?=h($category)?> ·</p><h1><?=h($p['name'])?></h1><?php if($p['short_description']):?><p class="lead"><?=h($p['short_description'])?></p><?php endif;?><?php if($p['description']):?><p><?=nl2br(h($p['description']))?></p><?php endif;?><dl><?php foreach([[$lang==='es'?'Nombre científico':'Scientific name',$p['scientific_name']],[$lang==='es'?'Partida arancelaria':'Tariff code',$p['tariff_code']],[$lang==='es'?'Calibre':'Caliber',$p['caliber']],[$lang==='es'?'Destinos principales':'Main destinations',$p['destinations']]] as [$label,$value]):if($value):?><div><dt><?=h($label)?></dt><dd><?=h($value)?></dd></div><?php endif;endforeach;?></dl><?php if($certs):?><div class="certs"><?php foreach($certs as $cert):?><span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 2 2.1 2.8-.2.8 2.7 2.4 1.5-1 2.6 1 2.6-2.4 1.5-.8 2.7-2.8-.2L12 21l-2-2.1-2.8.2-.8-2.7L4 14.9l1-2.6-1-2.6 2.4-1.5.8-2.7 2.8.2L12 3Z"/><path d="m9 12 2 2 4-4"/></svg><?=h($cert)?></span><?php endforeach;?></div><?php endif;?><div class="product-actions"><a class="primary" href="<?=h($contact.'?product='.rawurlencode($p['name']))?>"><?=$lang==='es'?'Solicitar cotización':'Request a quote'?><svg viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></a><?php if($p['technical_sheet_path']):?><a class="secondary" href="<?=h($p['technical_sheet_path'])?>" target="_blank"><?=$lang==='es'?'Ficha técnica':'Technical sheet'?><svg viewBox="0 0 24 24"><path d="M12 3v12m-4-4 4 4 4-4M5 20h14"/></svg></a><?php endif;?></div></article></section><?php if($packages):?><section class="pd-section"><header><p class="eyebrow">· <?=$lang==='es'?'PRESENTACIONES':'PACKAGING'?> ·</p><h2><?=$lang==='es'?'Empaque disponible':'Available packaging'?></h2></header><div class="package-grid"><?php foreach($packages as $pack):?><article><svg viewBox="0 0 24 24"><path d="M7 4h10l2 16H5L7 4Z"/><path d="M9 8h6"/></svg><strong><?=h($pack['weight_primary'])?></strong><?php if($pack['weight_secondary']):?><span><?=h($pack['weight_secondary'])?></span><?php endif;?><p><?=h($lang==='es'?$pack['material_es']:$pack['material_en'])?></p></article><?php endforeach;?></div></section><?php endif;?><?php if($harvest):?><section class="pd-section harvest-section"><header><p class="eyebrow">· <?=$lang==='es'?'DISPONIBILIDAD':'AVAILABILITY'?> ·</p><h2><?=$lang==='es'?'Calendario de cosecha':'Harvest calendar'?></h2></header><div class="harvest-grid"><?php foreach($months as $i=>$month):$status=$harvest[$i+1]??'none';?><div class="<?=h($status)?>"><span><?=h($month)?></span><i></i></div><?php endforeach;?></div><div class="legend"><span class="harvest">● <?=$lang==='es'?'Cosecha':'Harvest'?></span><span class="available">● <?=$lang==='es'?'Disponible':'Available'?></span><span class="limited">● <?=$lang==='es'?'Limitado':'Limited'?></span></div></section><?php endif;?><?php if($related):?><section class="pd-section related-section"><header><p class="eyebrow">· <?=$lang==='es'?'TAMBIÉN TE PUEDE INTERESAR':'YOU MAY ALSO LIKE'?> ·</p><h2><?=$lang==='es'?'Productos relacionados':'Related products'?></h2></header><div class="related-grid"><?php foreach($related as $item):?><a href="<?=h($base.$item['slug'].'/')?>"><img src="<?=h($item['image_path'])?>" alt="<?=h($item['name'])?>"><span><?=h($lang==='es'?$item['name_es']:$item['name_en'])?></span><strong><?=h($item['name'])?></strong><svg viewBox="0 0 24 24"><path d="M7 17 17 7M9 7h8v8"/></svg></a><?php endforeach;?></div></section><?php endif;?><section class="pd-cta"><div><p class="eyebrow">· <?=$lang==='es'?'HABLEMOS DE NEGOCIOS':'LET’S TALK BUSINESS'?> ·</p><h2><?=$lang==='es'?'Llevemos este producto a nuevos mercados.':'Let’s take this product to new markets.'?></h2></div><a href="<?=h($contact.'?product='.rawurlencode($p['name']))?>"><?=$lang==='es'?'Contáctanos':'Contact us'?><svg viewBox="0 0 24 24"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></a></section></main><footer><a class="pd-brand" href="/"><img src="/images/logo.webp" alt=""><span><strong>ROYAL BEANS</strong><small>· PERÚ ·</small></span></a><p>© <?=date('Y')?> Royal Beans Perú S.A.C.</p></footer><script>document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#main-product-image').src=b.dataset.image;document.querySelectorAll('[data-image]').forEach(x=>x.classList.remove('active'));b.classList.add('active')}));</script></body></html>
